def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    me = [h[0] for h in history]
    op = [h[1] for h in history]
    op_c = op.count('C')
    op_d = n - op_c

    if n < 3:
        return 'C'

    # Always-defect opponent: defect to minimize losses.
    if op_c == 0:
        return 'D'

    # Always-cooperate opponent: exploit steadily, but keep early rounds clean.
    if op_d == 0:
        if n < 2:
            return 'C'
        if n >= 96:
            return 'D'
        # Occasional probe, otherwise keep farming mutual cooperation.
        if n > 8 and n % 5 == 0:
            return 'D'
        return 'C'

    # Recent window analysis.
    w = min(8, n)
    recent_op = op[-w:]
    recent_me = me[-w:]
    roc = recent_op.count('C')
    rod = w - roc
    rmc = recent_me.count('C')

    # Consecutive defections by opponent.
    run_d = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'D':
            run_d += 1
        else:
            break

    # Consecutive cooperations by opponent.
    run_c = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'C':
            run_c += 1
        else:
            break

    # Near the end, defect to exploit likely cooperators.
    remaining = 100 - n
    if remaining <= 3:
        if op_c * 2 >= n:
            return 'D'
        if op[-1] == 'D' and run_d >= 2:
            return 'D'
        return 'D' if op_c * 3 >= n else 'C'

    if remaining <= 10:
        if op_c * 5 >= n * 3:
            return 'D'
        if run_d >= 2:
            return 'D'
        if op[-1] == 'C' and run_c >= 2:
            return 'C'
        return 'C'

    # If opponent heavily defects, defect back.
    if op_d * 3 > n * 2:
        return 'D'

    # If opponent recently mostly defected, retaliate.
    if rod >= 5:
        return 'D'

    # If we are in a mutual defection trap, try to break out.
    if op[-1] == 'D' and me[-1] == 'D':
        if run_d >= 3:
            # Long punishment; occasionally forgive to restore cooperation.
            if rng.random() < 0.3:
                return 'C'
            return 'D'
        return 'C'

    # Opponent just defected after likely cooperation.
    if op[-1] == 'D':
        if run_d == 1 and op_c * 3 >= n * 2:
            # Isolated defection: retaliate once but be ready to forgive.
            if me[-1] == 'D':
                return 'C'
            return 'D'
        if run_d >= 2:
            return 'D'
        if op_d * 2 >= n:
            return 'D'
        return 'D'

    # Opponent cooperated last.
    if op[-1] == 'C':
        # If opponent is otherwise nice, cooperate, but probe occasionally.
        if op_c * 4 >= n * 3:
            if n > 15 and n % 7 == 0 and rng.random() < 0.4:
                return 'D'
            return 'C'
        # Mixed opponent: cooperate if recent behavior acceptable.
        if roc * 2 >= w:
            return 'C'
        if rmc > 3 and rod > 3:
            return 'D'
        return 'C'

    return 'C'
